from ta_moler.device.nokia_unix_remote import NokiaUnixRemote
from moler.helpers import call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class Egen3(NokiaUnixRemote):
    r"""
    Egen device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      EGEN:
       DEVICE_CLASS: ta_moler.device.egen3.Egen3
       CONNECTION_HOPS:
         PROXY_PC:
           UNIX_REMOTE:
             execute_command: ssh # default value
             command_params:
               expected_prompt: unix_remote_prompt
               host: host_ip
               login: login
               password: password
         UNIX_REMOTE:
           PROXY_PC:
             execute_command: exit # default value
             command_params:
               expected_prompt: proxy_pc_prompt
         UNIX_LOCAL:
           PROXY_PC:
             execute_command: ssh # default value
             command_params:
               expected_prompt: proxy_pc_prompt
               host: host_ip
               login: login
               password: password
    -without PROXY_PC:
      EGEN:
       DEVICE_CLASS: ta_moler.device.egen3.Egen3
       CONNECTION_HOPS:
         UNIX_LOCAL:
           UNIX_REMOTE:
             execute_command: ssh # default value
             command_params:
               expected_prompt: unix_remote_prompt
               host: host_ip
               login: login
               password: password
    """

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(Egen3, self)._get_packages_for_state(state, observer)

        if available and state in [Egen3.unix_remote, Egen3.unix_remote_root]:
            if observer is Egen3.cmds:
                available.append('ta_moler.cmd.egen')
            elif observer is Egen3.events:
                available.append('ta_moler.events.egen')
            return available

        return available
